# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Find a minimum-cost shared directed broadcast tree, then reuse it per partition."""
    import heapq

    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(dst for dst in dsts if dst != src))
    h = G.copy()
    h.remove_edges_from(
        list(h.in_edges(src)) + list(nx.selfloop_edges(h)) +
        [(u, v) for u, v, data in h.edges(data=True) if data.get("cost") is None]
    )

    # A relay is useful only when it is both source-reachable and can reach a
    # requested destination. This makes the exact subset DP much smaller.
    if terminals and src in h and all(dst in h for dst in terminals):
        useful = {src}
        useful.update(nx.descendants(h, src))
        backwards = set()
        for dst in terminals:
            backwards.add(dst)
            backwards.update(nx.ancestors(h, dst))
        relevant = useful & backwards
        if all(dst in relevant for dst in terminals):
            h = h.subgraph(relevant).copy()

    def install(edges):
        tree = nx.DiGraph()
        tree.add_edges_from(edges)
        for dst in dsts:
            if dst == src:
                route = []
            else:
                try:
                    nodes = nx.dijkstra_path(tree, src, dst, weight=lambda u, v, d: G[u][v]["cost"])
                except nx.NetworkXNoPath:
                    nodes = nx.dijkstra_path(h, src, dst, weight="cost")
                route = [[u, v, G[u][v]] for u, v in zip(nodes, nodes[1:])]
            for partition in range(num_partitions):
                topology.set_dst_partition_paths(dst, partition, list(route))

    # Dreyfus-Wagner DP: dp[mask][v] is the cheapest subtree rooted at v
    # reaching all terminal bits in mask. Reverse Dijkstra adds a shared stem.
    if src in h and len(terminals) <= 12:
        nodes = list(h)
        pos = {node: i for i, node in enumerate(nodes)}
        n, size, inf = len(nodes), 1 << len(terminals), float("inf")
        reverse = {}
        for u, v, data in h.edges(data=True):
            reverse.setdefault(v, []).append((u, data["cost"]))

        dp = [[inf] * n for _ in range(size)]
        choice = [[None] * n for _ in range(size)]
        for mask in range(1, size):
            if mask & (mask - 1) == 0:
                terminal = terminals[mask.bit_length() - 1]
                if terminal in pos:
                    dp[mask][pos[terminal]] = 0
                    choice[mask][pos[terminal]] = ("t",)

            sub = (mask - 1) & mask
            while sub:
                other = mask ^ sub
                if sub < other:
                    for i in range(n):
                        value = dp[sub][i] + dp[other][i]
                        if value < dp[mask][i]:
                            dp[mask][i] = value
                            choice[mask][i] = ("s", sub, other)
                sub = (sub - 1) & mask

            queue = [(dp[mask][i], nodes[i]) for i in range(n) if dp[mask][i] < inf]
            heapq.heapify(queue)
            while queue:
                value, v = heapq.heappop(queue)
                vi = pos[v]
                if value != dp[mask][vi]:
                    continue
                for u, cost in reverse.get(v, []):
                    ui = pos[u]
                    if value + cost < dp[mask][ui]:
                        dp[mask][ui] = value + cost
                        choice[mask][ui] = ("e", v)
                        heapq.heappush(queue, (value + cost, u))

        full = size - 1
        if not terminals:
            install([])
            return topology
        if dp[full][pos[src]] < inf:
            edges = set()

            def expand(mask, node):
                decision = choice[mask][pos[node]]
                if decision[0] == "e":
                    edges.add((node, decision[1]))
                    expand(mask, decision[1])
                elif decision[0] == "s":
                    expand(decision[1], node)
                    expand(decision[2], node)

            expand(full, src)
            install(edges)
            return topology

    # Larger destination sets use low marginal-cost attachment to preserve
    # already paid broadcast prefixes.
    reached, pending, edges = {src}, set(terminals), set()
    while pending:
        distances, paths = nx.multi_source_dijkstra(
            h, reached, weight=lambda u, v, d: 0 if (u, v) in edges else d["cost"]
        )
        candidates = [dst for dst in pending if dst in distances]
        if not candidates:
            break
        path = paths[min(candidates, key=distances.get)]
        edges.update(zip(path, path[1:]))
        reached.update(path)
        pending.difference_update(reached)

    install(edges)
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


